head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnDataListInfo]<br/>Body Column 정보를 사용하여 특정 Column 에 바인딩된 DataList 정보를 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 아이템으로 바인딩된 DataList 정보를 조회할 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "inputType='select','autoComplete','checkcombobox' 인 Column 의 아이템이 DataList 로 정의된 경우에 동작합니다.",
        "반환된 객체의 result.nodeset 은 아이템이 정의된 DataList 의 ID 를 'data:[DataList ID]' 형식으로 갖습니다.",
        "반환된 객체의 result.id 는 아이템이 정의된 DataList 의 ID 를 갖습니다.",
        "반환된 객체의 result.value 는 아이템의 Value 값과 바인딩 된 Column 의 ID 를 갖습니다.",
        "반환된 객체의 result.label 은 아이템의 Label 값과 바인딩 된 Column 의 ID 를 갖습니다.",
        "아이템이 ItemSet 으로 정의되었거나 지원하지 않는 inputType 의 Column 은 null 값을 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - 옵션용 DataList(dlt_grade) : value ref=code, label ref=label
//  - select/checkcombobox/autoComplete Column 은 dlt_grade 를 itemset 으로 바인딩 -> 객체 반환
//  - text Column / 인라인 정적 ItemSet select Column 은 null 반환
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_grade !== 'undefined') {
        $p.data.remove("dlt_grade");
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column 인덱스 - 0:name(text) / 1:memo(text, 숨김 setColumnVisible(1,false)) / 2:grade(select, dlt_grade itemset) / 3:region(checkcombobox, dlt_grade itemset) / 4:city(autoComplete, dlt_grade itemset) / 5:staticSel(select, 인라인 정적 ItemSet). 숨김 컬럼도 포함하여 인덱스가 부여됨. dlt_grade 는 value=code, label=label 로 바인딩.\n[절차] columnInfo(인덱스) 선택 후 (getColumnDataListInfo 실행) 클릭.\n[확인] select/checkcombobox/autoComplete(2/3/4)=DataList 정보 객체(nodeset=data:dlt_grade, id=dlt_grade, value=code, label=label) / text(0) 와 정적 ItemSet select(5)=null 가 반환영역에 출력됨."', '', 'label1');

    // 옵션용 DataList (코드/라벨) - value=code, label=label
    let strGrade = '';
    strGrade += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_grade" baseNode="list" repeatNode="map">';
    strGrade += '<w2:columnInfo>';
    strGrade += '<w2:column id="code" name="code" dataType="text"></w2:column>';
    strGrade += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strGrade += '</w2:columnInfo>';
    strGrade += '<w2:data use="true"></w2:data>';
    strGrade += '</w2:dataList>';
    $p.data.create(strGrade);
    dlt_grade.setJSON([
        { "code": "A", "label": "최우수" },
        { "code": "B", "label": "우수" },
        { "code": "C", "label": "보통" }
    ], false);

    // GridView 와 바인딩할 DataList 동적 생성 (각 Column 별 데이터)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="grade" name="grade" dataType="text"></w2:column>';
    strDlt += '<w2:column id="region" name="region" dataType="text"></w2:column>';
    strDlt += '<w2:column id="city" name="city" dataType="text"></w2:column>';
    strDlt += '<w2:column id="staticSel" name="staticSel" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // checkcombobox(region) 다중값은 공백 구분 코드값
    let jsonData = [
        { "name": "노트북", "memo": "재고확인", "grade": "A", "region": "A B", "city": "A", "staticSel": "1" },
        { "name": "모니터", "memo": "신규입고", "grade": "B", "region": "B C", "city": "B", "staticSel": "2" },
        { "name": "키보드", "memo": "할인적용", "grade": "C", "region": "A C", "city": "C", "staticSel": "1" },
        { "name": "마우스", "memo": "주문대기", "grade": "A", "region": "B", "city": "A", "staticSel": "2" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // itemset 공통 조각 (select/checkcombobox/autoComplete 용) : value ref=code, label ref=label
    let itemset = '<w2:choices><w2:itemset nodeset="data:dlt_grade"><w2:label ref="label"></w2:label><w2:value ref="code"></w2:value></w2:itemset></w2:choices>';
    // 인라인 정적 ItemSet (DataList 아님) - null 반환 검증용
    let staticItemset = '<w2:choices><w2:item><w2:label>유형1</w2:label><w2:value>1</w2:value></w2:item><w2:item><w2:label>유형2</w2:label><w2:value>2</w2:value></w2:item></w2:choices>';

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:100%;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getColumnDataListInfo 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="90" inputType="text" id="h0" value="name(text)"></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="h1" value="memo(숨김)"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="h2" value="grade(select)"></w2:column>';
    strTarget += '<w2:column width="140" inputType="text" id="h3" value="region(checkcombobox)"></w2:column>';
    strTarget += '<w2:column width="130" inputType="text" id="h4" value="city(autoComplete)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="h5" value="staticSel(정적select)"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="brow1">';
    //  (중요) body 컬럼 id 는 dataList 컬럼 id 와 동일해야 셀에 데이터가 바인딩됨
    // 0 name (text) -> 미지원 inputType -> null
    strTarget += '<w2:column width="90" inputType="text" id="name" dataList="name"></w2:column>';
    // 1 memo (text) -> setColumnVisible(1,false) 로 숨김 (숨김 포함 인덱스 검증용)
    strTarget += '<w2:column width="100" inputType="text" id="memo" dataList="memo"></w2:column>';
    // 2 grade (select, dlt_grade itemset) -> 객체 반환
    strTarget += '<w2:column width="120" inputType="select" id="grade" dataList="grade">' + itemset + '</w2:column>';
    // 3 region (checkcombobox, dlt_grade itemset) -> 객체 반환
    strTarget += '<w2:column width="140" inputType="checkcombobox" id="region" dataList="region">' + itemset + '</w2:column>';
    // 4 city (autoComplete, dlt_grade itemset) -> 객체 반환
    strTarget += '<w2:column width="130" inputType="autoComplete" id="city" dataList="city">' + itemset + '</w2:column>';
    // 5 staticSel (select, 인라인 정적 ItemSet -> DataList 아님) -> null
    strTarget += '<w2:column width="*" inputType="select" id="staticSel" dataList="staticSel">' + staticItemset + '</w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 두번째 Column(memo, 인덱스 1) 숨김 -> 숨김 Column 포함 인덱스 검증용
    target1.setColumnVisible(1, false);
}



// getColumnDataListInfo 조회 (메인 검증)
//  - select/checkcombobox/autoComplete + DataList itemset Column -> 객체 반환
//  - text / 정적 ItemSet Column -> null
scwin.btn_getColumnDataListInfo_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());

    let colID = target1.getColumnID(columnInfo);
    let info = target1.getColumnDataListInfo(columnInfo);

    let result = (info === null || typeof info === 'undefined') ? "null" : JSON.stringify(info);

    wf_body_bottom.getObj("scwin").setReturnValue("getColumnDataListInfo(" + columnInfo + ") [getColumnID:" + colID + "] -> " + result);
}
